<?php $u = App\Models\User::find(7); $req = request()->merge(["vendor_id" => 1, "counted_cash" => 1000, "counted_terminal" => 200000, "notes" => "3000 was given to"]); $req->setUserResolver(fn() => $u); try { $s = App\Models\PosSession::where("cashier_id", 7)->whereDate("business_date", now()->toDateString())->first(); $res = app(App\Http\Controllers\Pos\PosSessionController::class)->close($req, $s); dump($res->getStatusCode(), $res->getContent()); } catch (\Exception $e) { dump($e->getMessage(), get_class($e)); }
